presetParts.comp:
#define sat saturate
sampler sampler_pw_noise_lq;
#define snl sampler_noise_lq
#define pnl sampler_pw_noise_lq
float3 ball,refl,bcol;
float2 uv1,uv2,uv3,uv4,dz,dz2,pro,h,v;
float str,ey,a,b,c,s,z,d,k1,p,q, alp,fl,struc,mask,dist,smask,bli;
static const float fov=q1,z0=q2,ym=q3,wid=q4,slots=q5,brad=q7;

float3 scol (float x) {x=x/(slots*2)+0.4; 
return .4+0.7*sat (0.5+sin(M_PI/6*(12*x+time/4+float3(3,-1,-5))));}

float getr (float2 uvi) {return 1/(.1+pow(1-GetPixel(uvi).r,2));}
float getr1 (float2 uvi) {return (1-pow(1-GetBlur1(uvi).r,2));}

float3 spa(float2 uvi,float t) 
{float3 tmp=0; float2 uv4,uv5=uvi; float3 m;
for (int n=1; n<6; n++)
{  uv5 = uvi*(1+n*0.5) +float2(n*0.1,t);
  m=tex2D(pnl,uv5.yx);
  tmp+=4*tex2D(snl,uv5)*(m>0.98)*sin(t*m.z*128);}
  return tmp+lum(tmp);}

float3 noise2(float2 uvi) {return tex2D(snl,uvi);}

shader_body {
//uv = ((uv-0.5)+float2(0,0.02))*0.96+0.5;
uv1 = float2 (uv.x-0.5, ym-uv.y)*fov;
dist=GetPixel(uv).b;
mask=GetPixel(uv).r>0.02;
struc=GetPixel(uv)*mask;
ey=1-(uv.y-ym)*dist*fov*z0;

if (uv1.y>0) { p=z0*uv1.x;  q=z0*uv1.y+M_PI/2+z0-1;} //hinten
else if (uv1.y<-1/(z0-1)) { q=-1/uv1.y*1; p=uv1.x*q;} //vorn
else 
  { a=-(1+uv1.y); b=2*uv1.y; c= 1+uv1.y*(z0-1);
    float bet=(b+sqrt(b*b-4*a*c))/(2*a); alp=bet*-(M_PI/2);
    q=alp-1+z0; p=uv1.x * (z0+sin(alp)-1);}
uv3 = float2(p,q);

ret = sat(16*abs(frac(p/wid+0.5)-0.5))/4;
str = int(p/wid);
smask=(str<slots)*(str>-slots); 
ret *= smask;

float2 ka=tex2D(pnl,uv3/wid/256);
ret *= (1+1*noise2(uv3*ka.y).x)*scol(str);

pro=noise2(uv3*ka.y).x-noise2(uv3*ka.y+0.001);
bli=pow((1-uv.x+pro.x*!mask),7);
ret*=(1+GetBlur1((uv+pro*0.05)).g*10); //shadows
ret *= 0.2+bli ;

k1=1+(1/dist);
h = float2 (k1,0)*texsize.zw;
v = float2 (0,k1)*texsize.zw;

dz.x = getr (uv+h) - getr (uv-h);
dz.y = getr (uv+v) - getr (uv-v);
dz *= mask*0.3;

//streifenbeleuchtung
s=(p/fov/z0+0.5) ;
uv4=frac(float2(s+dz.x*-.02*(1+ey),wid/fov/z0/2));
fl = lerp (GetBlur1(uv4),GetBlur1(uv4),!mask).g*1.5;

//#######################################################
uv4=frac(float2(s,0)+float2(0,wid/fov/z0/2));
float bb=GetPixel(uv4).b;
float ll=(4*pow(sin(q10*8-0.5*uv.x*M_PI),1114));
fl += sat(1-pow(q-7,2)*(3*bb)+2*pro) * bb * (1+0*ll) * !mask;

ret += fl*sat(0.5+q/z0)*scol(str);

ball=dz.y/3;

bcol=scol(+p/wid*sat(1-ey*(1-dist)));
refl=(sat(-dz.y)*(0.5+4*fl))*bcol;
ball+=refl*sat(1-ey*0.);

//lichtreflektion
ball += lum(GetBlur1(frac(uv-dz*0.7)))*mask*bcol;
k1=2+(1-dist)*6;
h = float2 (k1,0)*texsize.zw;
v = float2 (0,k1)*texsize.zw;

dz2.x = getr1 (uv+h) - getr1 (uv-h);
dz2.y = getr1 (uv+v) - getr1 (uv-v);
ball += 0.03/length(dz2-0.2*uv)*struc*(1+bcol);
ball *= 1-dist/3;

k1 = 0.1/length(cos(42*uv*float2(1,0.08)+float2((uv.y)*3*uv1.x,0)));
ret = lerp(ret,k1* (2+spa(uv,q11*(floor(k1*32)/4)))*(.5+scol(p/wid)),!smask);

ret = lerp (ret,ball,mask);
//ret = GetPixel(uv);
}
